import{_ as t,o,c as a,a3 as s}from"./chunks/framework.DAK02U1-.js";const u=JSON.parse('{"title":"Capture Backends","description":"","frontmatter":{"head":[["meta",{"property":"og:title","content":"Capture Backends | clice.io"}],["meta",{"property":"og:url","content":"https://docs.clice.io/catter/design/capture-backends"}],["meta",{"property":"og:image","content":"https://docs.clice.io/og.png"}],["meta",{"property":"og:image:width","content":"1200"}],["meta",{"property":"og:image:height","content":"630"}],["meta",{"property":"og:locale","content":"en_US"}],["link",{"rel":"canonical","href":"https://docs.clice.io/catter/design/capture-backends"}],["link",{"rel":"alternate","hreflang":"en","href":"https://docs.clice.io/catter/design/capture-backends"}],["link",{"rel":"alternate","hreflang":"x-default","href":"https://docs.clice.io/catter/design/capture-backends"}],["link",{"rel":"alternate","hreflang":"zh-CN","href":"https://docs.clice.io/zh/catter/design/capture-backends"}]]},"headers":[],"relativePath":"catter/design/capture-backends.md","filePath":"en/catter/design/capture-backends.md","lastUpdated":1793198831000}'),r={name:"catter/design/capture-backends.md"};function d(n,e,i,c,h,l){return o(),a("div",null,[...e[0]||(e[0]=[s('<h1 id="capture-backends" tabindex="-1">Capture Backends <a class="header-anchor" href="#capture-backends" aria-label="Permalink to &quot;Capture Backends&quot;">​</a></h1><p>A capture backend is how catter gets a build&#39;s commands: it starts the build, and reports each command the build starts to catter, which has the session&#39;s handlers decide it and tells them how it ended. The handlers see the same commands, decisions and events whichever backend reports them.</p><h2 id="choosing-one" tabindex="-1">Choosing one <a class="header-anchor" href="#choosing-one" aria-label="Permalink to &quot;Choosing one&quot;">​</a></h2><p><code>--capture &lt;backend&gt;</code> names the backend that captures the build: <code>hook</code>, the default, <code>wrapper</code>, <code>eslogger</code>, on macOS, or <code>ptrace</code>, on Linux. <code>--from &lt;file&gt;</code> replays a recorded build instead of running one: a recorded build is not captured, so <code>--from</code> takes no <code>--capture</code>, and a name no backend has is an error too. Both are reported before anything runs.</p><p>A handler learns the backend from the session&#39;s <code>initialize</code> message, whose <code>mode</code> is its name, or <code>replay</code> for a recorded build, and whose <code>decisions</code> says whether the build&#39;s commands wait for the handlers&#39; decisions.</p><h2 id="what-a-backend-does" tabindex="-1">What a backend does <a class="header-anchor" href="#what-a-backend-does" aria-label="Permalink to &quot;What a backend does&quot;">​</a></h2><ul><li><strong>It starts the build</strong>, and catter ends as the build did. catter stands in for the build command: a SIGTERM, SIGINT or SIGHUP sent to catter goes on to it, and the build command ends when catter is killed, but under <code>eslogger</code>.</li><li><strong>It reports each command</strong>: its working directory, program, arguments and environment, and the command that started it. The commands of a parallel build come at once. A command catter could not capture comes as an <code>error</code> instead.</li><li><strong>It follows the handlers&#39; decisions, or only observes.</strong> A backend that follows them reports each command before it runs, and runs it as the handlers decide: as it is (<code>skip</code>), changed (<code>modify</code>, <code>edit</code>), or not at all (<code>drop</code>, which ends it with exit code 0). A backend that only observes hears of each command once it runs, which no decision changes then: catter refuses a handler that decides (<code>decides</code> in its answer to <code>initialize</code>) before the build starts, and names it.</li><li><strong>A handler that aborts the build or fails ends the session</strong>: no handler is told anything after it. A command that has started runs on. Under a backend that follows decisions, the command being decided and every command the build starts after it end with exit code 1 without running; under one that only observes, every command has started by the time catter hears of it, and the build runs on to its end. catter then exits 1.</li><li><strong>It reports how each command ended</strong>, before any command the build starts once that command has ended, and before the build&#39;s own end.</li></ul><h2 id="backends" tabindex="-1">Backends <a class="header-anchor" href="#backends" aria-label="Permalink to &quot;Backends&quot;">​</a></h2><h3 id="hook-default" tabindex="-1">hook (default) <a class="header-anchor" href="#hook-default" aria-label="Permalink to &quot;hook (default)&quot;">​</a></h3><ul><li><strong>How it works</strong>: a hook library is loaded into every process of the build and intercepts process creation (the <code>execve</code> / <code>posix_spawn</code> family on Linux and macOS, <code>CreateProcess</code> on Windows). On Linux and macOS each command then runs through <code>catter-proxy</code>, which asks catter and runs the command as decided, with the hook; on Windows the hook asks catter itself, and starts the program as catter decides. See <a href="./hook-mechanism">Hook mechanism</a> and <a href="./ipc-protocol">IPC protocol</a>.</li><li><strong>Platforms</strong>: Linux, macOS, Windows.</li><li><strong>What it sees</strong>: every process of the build, each with the command that started it, but for what a program the hook cannot be loaded into starts: the program is reported and runs as decided, without the hook. On macOS those are Apple&#39;s own tools (<code>/bin/sh</code>, <code>/usr/bin/make</code>), which run as arm64e and from which System Integrity Protection drops the hook, and Intel programs under Rosetta; on Windows, 32-bit (x86) programs. A program a Windows program starts under another account is not seen at all.</li><li>The build and its commands run on catter&#39;s own stdin, stdout and stderr: they write straight to the terminal, with their colors and in the order they write.</li></ul><h3 id="eslogger-macos" tabindex="-1">eslogger (macOS) <a class="header-anchor" href="#eslogger-macos" aria-label="Permalink to &quot;eslogger (macOS)&quot;">​</a></h3><ul><li><strong>How it works</strong>: catter runs the build as it is, and Endpoint Security, the macOS interface for observing processes, reports every process the build starts through <code>eslogger</code>, the program macOS has for it (<code>eslogger exec fork exit</code>). catter follows the build&#39;s processes from the build command&#39;s: each program a process of the build runs is a command, whose parent is the program its process ran before it, or the command whose process forked its own. catter reads a command once it runs, and the build never waits for catter.</li><li><strong>Platforms</strong>: macOS.</li><li><strong>What it needs</strong>: root, through <code>sudo</code>, for eslogger: sudo asks for the password on the terminal before the build starts, and catter refuses to run where it cannot, unless sudo runs <code>/usr/bin/eslogger</code> without a password. Endpoint Security takes no program without Full Disk Access for the app catter runs in: Terminal, or another terminal app, in System Settings &gt; Privacy &amp; Security &gt; Full Disk Access; over SSH, &quot;Allow full disk access for remote users&quot; in the settings of Remote Login.</li><li><strong>What it sees</strong>: every program the build&#39;s processes run, Apple&#39;s own tools (<code>/bin/sh</code>, <code>/usr/bin/make</code>, <code>xcodebuild</code>) and what they start included. A program that <code>/usr/bin/cc</code> or <code>/bin/sh</code> runs in its place (Xcode&#39;s <code>clang</code>, <code>bash</code>) is a command of its own, a child of the one it replaced. A process the build does not start itself, as a service started by <code>launchd</code> on the build&#39;s behalf or a server started before the build, is not seen, and neither is a program that fails to start.</li><li><strong>Actions</strong>: none; a handler that decides is refused.</li><li><strong>Costs</strong>: catter waits for eslogger to report before it starts the build, and for its last events once the build has ended: about a second in all. eslogger may fall behind a build that starts many processes at once: catter takes every event, which can take seconds after the build has ended. Endpoint Security may drop events eslogger falls far behind on: catter warns how many of the system&#39;s it dropped while the build ran, and commands of the build may be missing, with every command a lost process started.</li><li><strong>Limitations</strong>: <ul><li>macOS ends no program with the one that started it: a build catter stands in for ends on SIGTERM, SIGINT and SIGHUP, which catter passes on, but not when catter is killed.</li><li>What catter reads of a command&#39;s files, such as its response files (<code>@file</code>), it reads once the command has run, or is running: a file the build removes once the command has run, as Ninja does a response file, may be gone.</li></ul></li></ul><h3 id="ptrace-linux" tabindex="-1">ptrace (Linux) <a class="header-anchor" href="#ptrace-linux" aria-label="Permalink to &quot;ptrace (Linux)&quot;">​</a></h3><ul><li><strong>How it works</strong>: catter runs the build traced, as a debugger follows a program: the kernel stops each process of the build as it starts a process or a thread, runs a program and ends, and catter reads the program it runs, its arguments, environment and working directory from <code>/proc</code> before the process goes on. catter follows the build&#39;s processes from the build command&#39;s, as under <code>eslogger</code>: each program a process of the build runs is a command, whose parent is the program its process ran before it, or the command whose process forked its own. A program runs once the handlers have been told of its command, whose files they read as they are then, but which no decision changes: catter never changes what a process runs.</li><li><strong>Platforms</strong>: Linux.</li><li><strong>What it needs</strong>: a system that lets a program trace its own children: <code>kernel.yama.ptrace_scope</code> 0 or 1, as most distributions set it, and in a container a profile that allows <code>ptrace</code>, as Docker&#39;s default does on Linux 4.8 and later. Where the system does not, catter says why before the build starts.</li><li><strong>What it sees</strong>: every program the build&#39;s processes run, a static program&#39;s and one a program starts without the C library included, as Go programs start theirs. A script is a command as the system runs it: its arguments are the interpreter its <code>#!</code> line names, the line&#39;s argument if it has one, then the script and the script&#39;s arguments. A process the build does not start itself, as a server started before the build, is not seen, and neither is a program that fails to start.</li><li><strong>Actions</strong>: none; a handler that decides is refused.</li><li><strong>Costs</strong>: no program starts in a command&#39;s place, and catter is told of no system call: the kernel stops a process of the build as it starts a process or a thread, runs a program and ends, and as a signal reaches it, while catter reads what it is told; a program waits at its start until the handlers have been told of its command. A make build of 1500 compiles took about an eighth longer than without catter, where the hook backend took a third longer.</li><li><strong>Limitations</strong>: <ul><li>Unless catter runs as root, a traced program runs without the privileges its file grants (set-user-ID, set-group-ID or capabilities), as it would under any debugger: <code>sudo</code> fails. catter warns of each such program; a build that needs one runs under <code>hook</code>.</li><li>A process has one tracer: a program of the build that traces another program of the build, as gdb, strace or a crash reporter does, fails to. So does LeakSanitizer, which a program built with AddressSanitizer runs at its exit: it fails, saying that LeakSanitizer does not work under ptrace, unless <code>ASAN_OPTIONS=detect_leaks=0</code> turns it off.</li><li>catter ends with the build command: a process the build leaves running then, as a build server, runs on untraced, and what it starts later is not seen.</li></ul></li></ul><h3 id="replay-from" tabindex="-1">replay (<code>--from</code>) <a class="header-anchor" href="#replay-from" aria-label="Permalink to &quot;replay (`--from`)&quot;">​</a></h3><ul><li><strong>How it works</strong>: it plays the build a file recorded instead of running one: each command, error and exit in the file&#39;s order, with the IDs and parent commands the file gives them. The build ends with the exit code the file records.</li><li><strong>Actions</strong>: nothing runs, so <code>skip</code>, <code>drop</code>, <code>modify</code> and <code>edit</code> change nothing. <code>abort</code> ends the replay as it ends a live build: no later event reaches the handlers, and catter exits 1.</li></ul><h3 id="wrapper" tabindex="-1">wrapper <a class="header-anchor" href="#wrapper" aria-label="Permalink to &quot;wrapper&quot;">​</a></h3><ul><li><strong>How it works</strong>: before each directory on the build&#39;s <code>PATH</code>, catter puts one of the session&#39;s own, with a shim of each compiler, linker and archiver it knows by its name there: whichever names a build tool looks for, and in whichever order, it finds the program it would without catter, through its shim. A variable such as <code>CC</code>, <code>CXX</code> or <code>AR</code> that names a program by its path names that program&#39;s shim instead, and CMake runs every compile and link through the wrapper backend&#39;s launcher (<code>CMAKE_&lt;LANG&gt;_COMPILER_LAUNCHER</code> and <code>CMAKE_&lt;LANG&gt;_LINKER_LAUNCHER</code>); on Windows MSBuild runs <code>cl.exe</code>, <code>link.exe</code> and <code>lib.exe</code> from the shims (<code>CLToolPath</code>, <code>LinkToolPath</code> and <code>LibToolPath</code>), each unless the build sets it. A shim is <code>catter-proxy</code>: it reports its command, runs the program it stands in for as decided, and reports how it ended. The program it runs finds no shims on its <code>PATH</code>: a compiler a build cache runs, as ccache runs the one past its own directory, is the compiler, not the shim again.</li><li><strong>Platforms</strong>: Linux, macOS, Windows.</li><li><strong>What it sees</strong>: the programs it has shims of, whatever in the build runs them, Apple&#39;s <code>/usr/bin/make</code> and <code>/bin/sh</code> included. A command&#39;s parent is the nearest program with a shim that started it, or the build command; what a compiler starts is not seen.</li><li><strong>Limitations</strong>: a build that runs a compiler by the path it found before catter ran, as the <code>build.ninja</code> CMake wrote does, escapes the shims: configure it and build it in one session, <code>catter compile-commands --capture wrapper -- sh -c &quot;cmake -B build &amp;&amp; cmake --build build&quot;</code>. The shims go with the session, so a build configured under the wrapper backend runs only in that session: configure one for catter of its own. A program the build puts first on <code>PATH</code> itself, as a toolchain&#39;s directory, is found before the shims, and one found through a relative entry of <code>PATH</code>, which names another directory wherever the build goes, has no shim. On Windows only <code>.exe</code> programs have shims, and a project that sets <code>CLToolPath</code>, <code>LinkToolPath</code> or <code>LibToolPath</code> itself, as a toolset other than MSVC&#39;s may, runs those tools past them.</li></ul><h2 id="capability-matrix" tabindex="-1">Capability matrix <a class="header-anchor" href="#capability-matrix" aria-label="Permalink to &quot;Capability matrix&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Backend</th><th>Platforms</th><th>How it captures</th><th>Actions</th><th>Parent command</th><th>Status</th></tr></thead><tbody><tr><td>hook</td><td>Linux / macOS / Windows</td><td>a hook in every process of the build</td><td><code>skip</code> <code>drop</code> <code>abort</code> <code>modify</code> <code>edit</code></td><td>the process that started it</td><td>implemented (default)</td></tr><tr><td>eslogger</td><td>macOS</td><td>Endpoint Security, through <code>eslogger</code></td><td>none: it only observes</td><td>the process that started it</td><td>implemented</td></tr><tr><td>ptrace</td><td>Linux</td><td>ptrace, as a debugger follows programs</td><td>none: it only observes</td><td>the process that started it</td><td>implemented</td></tr><tr><td>replay</td><td>any</td><td>a recorded build (<code>--from</code>)</td><td>only <code>abort</code> takes effect</td><td>as recorded</td><td>implemented</td></tr><tr><td>wrapper</td><td>Linux / macOS / Windows</td><td>compiler shims on <code>PATH</code>, <code>CC</code> / <code>CXX</code></td><td><code>skip</code> <code>drop</code> <code>abort</code> <code>modify</code> <code>edit</code></td><td>the nearest wrapped program</td><td>implemented</td></tr></tbody></table><h2 id="writing-handlers-for-any-backend" tabindex="-1">Writing handlers for any backend <a class="header-anchor" href="#writing-handlers-for-any-backend" aria-label="Permalink to &quot;Writing handlers for any backend&quot;">​</a></h2><ul><li>Do not assume one: <code>initialize</code> names it (<code>mode</code>), and says whether the commands wait for decisions (<code>decisions</code>). A handler that can do without deciding answers <code>decides</code> as <code>decisions</code> says.</li><li>A command&#39;s parent is the command that started it as far as the backend sees: features that rely on the process tree (command trees, target trees) should not assume every process in between is there.</li></ul>',22)])])}const p=t(r,[["render",d]]);export{u as __pageData,p as default};
